<?php
$z=new ZipArchive; $z->open(__DIR__.'/../Bazar.xlsx');
$strings=[]; $sx=simplexml_load_string($z->getFromName('xl/sharedStrings.xml')); foreach($sx->si as $s){$v='';foreach($s->xpath('.//*[local-name()="t"]')?:[] as $t)$v.=(string)$t; if(!$v){$v=(string)$s->t;foreach($s->r as $r)$v.=(string)$r->t;}$strings[]=$v;}
$wb=simplexml_load_string($z->getFromName('xl/workbook.xml')); $rels=simplexml_load_string($z->getFromName('xl/_rels/workbook.xml.rels')); $targets=[];foreach($rels as $r)$targets[(string)$r['Id']]=(string)$r['Target'];
$out=[];foreach($wb->sheets->sheet as $sheet){$rid=(string)$sheet->attributes('http://schemas.openxmlformats.org/officeDocument/2006/relationships')->id;$path=$targets[$rid];$xml=simplexml_load_string($z->getFromName(str_starts_with($path,'/')?ltrim($path,'/'):'xl/'.$path));$rows=[];$formulas=0;$errors=[];foreach($xml->sheetData->row as $row){$cells=[];foreach($row->c as $c){$v=(string)$c->v;if((string)$c['t']==='s')$v=$strings[(int)$v]??$v;if((string)$c['t']==='inlineStr')$v=(string)$c->is->t;$f=(string)$c->f;if($f)$formulas++;if((string)$c['t']==='e')$errors[]=[(string)$c['r'],$v];if($v!==''||$f)$cells[(string)$c['r']]=['value'=>$v,'formula'=>$f];}if($cells)$rows[]=$cells;}$out[]=['sheet'=>(string)$sheet['name'],'formulas'=>$formulas,'errors'=>$errors,'rows'=>$rows];}
file_put_contents(__DIR__.'/../docs/workbook-data.json',json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));foreach($out as $s){echo $s['sheet'].' rows='.count($s['rows']).' formulas='.$s['formulas'].' errors='.count($s['errors']).PHP_EOL;echo json_encode(array_slice($s['rows'],0,7),JSON_UNESCAPED_UNICODE).PHP_EOL;}
